      "parent": "38a61e961b7cfa64b2ca97603e1410c2cc43b47cba395d16f94b161067b5eda0",
      "rule": {
        "family": "relative_strength",
        "threshold": 0.05,
        "horizon": 7,
        "action": "long"
      },
      "genes": {
        "family": "K",
        "asset_weight_cap": 0.15,
        "correlation_cap": 0.5,
        "rebalance_days": 28,
        "trend_days": 160,
        "vol_days": 20,
        "vol_target": 0.1
      },
      "mechanism": "Long positions based on a lower relative strength threshold (0.05) with fewer asset weight caps. Longer trend lookback (160) smooths trend signal, while 28-day rebalance reduces trading costs. Volatility target (10%) scales exposure inversely to recent 20-day volatility. Expected: capture more frequent small RS signals while maintaining risk control through vol targeting.",
      "falsification": "If performance degrades due to excessive turnover or lower signal quality, as measured by increased drawdown or cost drag relative to parent."
    },
    {
      "parent": "097ae79017e295033aadb5f57e2b915cb5c2c96b87c5823ebb38aafd06d0a76f",
      "rule": {
        "family": "stop_trail_context",
        "threshold": 0.05,
        "horizon": 14,
        "action": "avoid"
      },
      "genes": {
        "family": "K",
        "asset_weight_cap": 0.1,
        "correlation_cap": 0.5,
        "rebalance_days": 7,
        "trend_days": 160,
        "vol_days": 20,
        "vol_target": 0.15
      },
      "mechanism": "Avoid positions when stop-trail context indicates potential downtrend with a looser threshold (0.05), using a longer trend filter (160 days) but higher vol target (15%). The higher vol target allows for larger position sizes when risk is deemed lower. Expected: reduce false positives in stop signals while maintaining growth potential.",
      "falsification": "If the looser threshold leads to more frequent whipsaws and higher drawdowns, or if the higher vol target increases volatility beyond tolerance."
    }
  ]
}

